176				"cluster. Other clusters' placements of the same upstream are " +
177				"unaffected. The cluster-host defaults to " + defaultClusterHost +
178				" when omitted.",
179			Example: "  entire repo mirror remove github.com/octocat/hello-world",
180			Args:    cobra.RangeArgs(1, 2),
181			RunE: func(cmd *cobra.Command, args []string) error {
182				owner, repo, err := parseGitHubURL(args[0])
183				if err != nil {
184					cmd.SilenceUsage = true
185					return fmt.Errorf("invalid <github-url>: %w", err)
186				}
187				clusterHost := clusterArg(args)
188				return runCore(cmd, func(ctx context.Context, c *coreapi.Client) error {
189					// Delete by upstream coords in one call. A 404 is a real
190					// error here, not idempotent success: the server only
191					// answers 204 when it actually removed a placement, so a
192					// 404 ("no such mirror / not visible / different cluster")
193					// surfaces verbatim via renderCoreError rather than being
194					// reported as a successful removal.
195					if err := c.DeleteMirror(ctx, coreapi.DeleteMirrorParams{
196						Provider:    coreapi.DeleteMirrorProviderGithub,
197						Owner:       owner,
198						Repo:        repo,
199						ClusterHost: clusterHost,
200					}); err != nil {
201						return err
202					}
203					cmd.Printf("Removed mirror github.com/%s/%s from %s\n", owner, repo, clusterHost)
204					return nil
205				})
206			},
207		}
208	}
