94	// ResolveCoreURL picks the entire-core URL the CLI should hit for STS
95	// exchange and refresh: the resolved context's CoreURL wins (the JWT's
96	// signed `iss` claim — authoritative). Falls back to ENTIRE_CORE_AUTH_BASE_URL
97	// for ENTIRE_TOKEN bypass and pre-login bootstrap, when no context yet
98	// exists. Trailing slashes normalised away.
99	//
100	// Without this, a binding to a context whose CoreURL is `eu` plus
101	// ENTIRE_CORE_AUTH_BASE_URL=us would post EU-issued JWTs to US — the
102	// exchange would (correctly) reject them. The context's CoreURL is the
103	// only URL where the JWT was minted.
104	func ResolveCoreURL(cfg Config) string {
105		if f, err := contexts.Load(cfg.ConfigDir); err == nil {
106			if c := f.Resolve(cfg.CredentialHost()); c != nil && c.CoreURL != "" {
107				return strings.TrimRight(c.CoreURL, "/")
108			}
109		}
110		return strings.TrimRight(cfg.EntireCoreBaseURL, "/")
111	}
