113	// GetTokenForHost retrieves the resolved context's access token from the
114	// keyring. ENTIRE_TOKEN, when set, bypasses the credential store
115	// entirely — useful when the keyring is unavailable or for CI runners
116	// injecting a workload JWT directly.
117	func GetTokenForHost(cfg Config) (string, error) {
118		if envToken := os.Getenv("ENTIRE_TOKEN"); envToken != "" {
119			return envToken, nil
120		}
121	
122		c, err := ResolveContext(cfg)
123		if err != nil {
124			return "", err
125		}
126		encodedToken, err := tokenstore.Get(c.KeychainService, c.Handle)
127		if err != nil {
128			return "", fmt.Errorf("failed to get token from keyring: %w", err)
129		}
130		token, _ := tokenstore.DecodeTokenWithExpiration(encodedToken)
131		return token, nil
132	}
